{
  "name": "rf_band_switch",
  "confidence": "medium",
  "docstring": "Handles an RF band-switch sequence, arming a timeout when requested and otherwise advancing or validating the switch, including BT/coexistence and PHY completion paths.",
  "subsystem": "rf",
  "var_renames": {
    "a1": "rf_ctx",
    "a2": "flags",
    "v3": "switch_seq",
    "v4": "band_state_ptr",
    "v7": "timer_now",
    "v8": "timer_state",
    "v9": "timer_handle"
  },
  "struct_hints": [
    {
      "offset": 4,
      "meaning": "RF/PHY context flags; bit 0x200 is cleared during band-switch handling"
    },
    {
      "offset": 107,
      "meaning": "BT/coexistence connection selector or index"
    },
    {
      "offset": 108,
      "meaning": "BT/coexistence or alternate-path flag"
    },
    {
      "offset": 115,
      "meaning": "Band-switch retry/sequence counter"
    },
    {
      "offset": 128,
      "meaning": "Band-switch pending/cancel flag"
    },
    {
      "offset": 20,
      "meaning": "Timer/context data field storing rf_ctx"
    },
    {
      "offset": 28,
      "meaning": "Timer/event identifier field (uint16_t)"
    },
    {
      "offset": 36,
      "meaning": "Timer flag cleared before arming the band-switch timer"
    }
  ]
}
